test('invoiceTotals: VAT calculation with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 20, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line total: 10 × 1000 = 10000 cents
  // Discount: 20% of 10000 = 2000 cents
  // After discount: 10000 - 2000 = 8000 cents
  // VAT: 21% of 8000 = 1680 cents
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 2000);
  assert.equal(totals.vat, 1680);
  assert.equal(totals.total, 9680);
});

test('invoiceTotals: total clamped at 0 even with VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 200, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Line total: 100 cents
  // Discount: 200% of 100 = 200 cents (clamped)
  // After discount: 100 - 200 = -100 → 0 cents (clamped)
  // VAT: 21% of 0 = 0 cents
  // Total: 100 - 200 + 0 = -100 → 0 cents (clamped)
  assert.equal(totals.total, 0);
});

