test('invoiceTotals: includes voucher in totals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const withVoucher = {
    ...invoiceResult.value,
    voucher: { code: 'PROMO10', amount: 10000 },
  };

  const totals = invoiceTotals(withVoucher);
  // DEV-HOUR: 5 × €95.00 = €475.00, VAT 21% = €99.75, Total = €574.75
  // With voucher: €574.75 - €100.00 = €474.75
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 47475);
});

